// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * RBAC — mirrors the upstream platform's model
 * (its organization schema):
 *
 *   Organizations.role_boundaries : List[Role]
 *   Role        = { name, permissions: [Permission] }
 *   Permission  = { object_name: "Actionable" | ...,
 *                   permission: "All" | "AssignedReadAll" | "AssignedReadUpdateAll" |
 *                               "SelfCreatedAll" | "DepartmentAssignedReadAll" |
 *                               "DepartmentAssignedReadUpdateAll" |
 *                               "BusinessUnitAssignedReadAll" |
 *                               "BusinessUnitAssignedReadUpdateAll" |
 *                               "ReporteeAssignedReadUpdateAll" }
 *   ExplicitPermission = per-user per-resource grants
 *                        (actions: read|write|delete|admin) that OVERRIDE roles.
 *
 * Engine resources are checked as object_name "Actionable":
 *   resource_type 'workflow' — definitions (no assignees; only All /
 *   SelfCreatedAll / explicit grants can mutate them)
 *   resource_type 'instance' — attached workflows (assignee-, department- and
 *   reportee-scoped literals apply against the step assignees and task department)
 */
import type { DirectoryUser } from './evaluator.ts';
import { DEFAULT_ORGANIZATION_ID } from './identity.ts';

/** `act` = change the state of a step one holds; the platform's rule is that an
 * assignee acts on their own step even when they may not edit the item. */
export type RbacAction = 'read' | 'write' | 'delete' | 'admin' | 'act';

/** 'directory' is org-wide: it has no owner, department or assignees, so only All (or an explicit directory grant) reaches it. */
export type RbacResourceType = 'workflow' | 'instance' | 'directory';

export type PermissionScope =
  | 'All'
  | 'OrganizationRead'
  | 'OrganizationReadUpdate'
  | 'AssignedReadAll'
  | 'AssignedReadUpdateAll'
  | 'SelfCreatedAll'
  | 'DepartmentAssignedReadAll'
  | 'DepartmentAssignedReadUpdateAll'
  | 'BusinessUnitAssignedReadAll'
  | 'BusinessUnitAssignedReadUpdateAll'
  | 'ReporteeAssignedReadUpdateAll';

export interface RolePermission {
  /** Platform Permission.object_name; omit = applies to every object. */
  object_name?: string;
  permission: PermissionScope;
}

export interface RoleBoundary {
  name: string;
  permissions: RolePermission[];
}

/** Platform ExplicitPermission (grants override role boundaries). */
export interface ExplicitGrant {
  user_id: string;
  /** 'object' grants come from the platform's per-record shares and name the
   * record (`<object type>:<object id>`), not an engine instance. */
  resource_type: RbacResourceType | 'object';
  resource_id: string;
  actions: RbacAction[];
  is_active?: boolean;
  /** ISO instant after which the grant gives nothing (platform shares expire). */
  expires_at?: string;
}

/** What a resource exposes for scope evaluation. */
export interface RbacResource {
  type: RbacResourceType;
  id: string;
  organization_id?: string;
  /** `<object type>:<object id>` of the record this instance runs for. */
  object_key?: string;
  /** Platform object; engine resources are "Actionable". */
  object_name?: string;
  /** Newly introduced object kinds can reject legacy unscoped role boundaries. */
  require_object_permission?: boolean;
  created_by?: string;
  /** User ids currently assigned (instance: union of active step assignees). */
  assignees?: string[];
  /** Department context (instance: task.department). */
  department?: string;
  /** Every department the object belongs to (instance: task.departments); a
   * platform task can sit in several. */
  departments?: string[];
  /** Business-unit context (instance: task.business_unit), scoping the matrix. */
  business_unit?: string;
}

/** One row of the platform's `ReportingMatrix`, optionally scoped to a business unit. */
export interface ReportingRow {
  reporting_manager: string;
  reportee: string;
  business_unit?: string;
}

const SUPERVISING_SCOPES = new Set<PermissionScope>([
  'All',
  'OrganizationReadUpdate',
  'BusinessUnitAssignedReadUpdateAll',
  'DepartmentAssignedReadUpdateAll',
]);

export class Rbac {
  private roles = new Map<string, Map<string, RoleBoundary>>();
  private grants = new Map<string, ExplicitGrant[]>();
  /**
   * reportee id → every manager of theirs (the platform's `ReportingMatrix` is a
   * LIST of {reporting_manager, reportee} rows, so one person legitimately has
   * several — a functional and an administrative manager, say). Storing a
   * single manager silently evicted all but the last row and denied the others
   * their reportee-scoped access with no error anywhere.
   *
   * Rows may be scoped to a business unit, mirroring
   * `BusinessUnit.reporting_matrix`; a row seeded without one applies
   * everywhere.
   */
  private managersOf = new Map<string, Map<string, ReportingRow[]>>();

  seedRoles(roles: RoleBoundary[], organizationId = DEFAULT_ORGANIZATION_ID): void {
    this.roles.set(organizationId, new Map(roles.map((r) => [r.name, r])));
  }

  seedGrants(grants: ExplicitGrant[], organizationId = DEFAULT_ORGANIZATION_ID): void {
    this.grants.set(organizationId, [...grants]);
  }

  /** Replaces the matrix. Every row is kept, including several per reportee. */
  seedReporting(rows: ReportingRow[], organizationId = DEFAULT_ORGANIZATION_ID): void {
    this.managersOf.set(organizationId, new Map());
    this.addReporting(rows, organizationId);
  }

  /** Merges rows in, ignoring exact duplicates. Used by directory seeding. */
  addReporting(rows: ReportingRow[], organizationId = DEFAULT_ORGANIZATION_ID): void {
    const orgRows = this.managersOf.get(organizationId) ?? new Map<string, ReportingRow[]>();
    this.managersOf.set(organizationId, orgRows);
    for (const row of rows) {
      if (!row?.reportee || !row?.reporting_manager) continue;
      const existing = orgRows.get(row.reportee) ?? [];
      const dup = existing.some(
        (r) => r.reporting_manager === row.reporting_manager && r.business_unit === row.business_unit,
      );
      if (!dup) orgRows.set(row.reportee, [...existing, row]);
    }
  }

  /** Everyone who reports to `manager` — the matrix read downward. */
  reportees(
    manager: string,
    businessUnit?: string,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): string[] {
    const out: string[] = [];
    for (const [reportee, rows] of this.managersOf.get(organizationId) ?? [])
      if (rows.some(
        (r) => r.reporting_manager === manager &&
          (r.business_unit === undefined || r.business_unit === businessUnit),
      )) out.push(reportee);
    return out;
  }

  /** Every manager of `reportee`, optionally narrowed to a business unit. */
  managers(
    reportee: string,
    businessUnit?: string,
    organizationId = DEFAULT_ORGANIZATION_ID,
  ): string[] {
    return (this.managersOf.get(organizationId)?.get(reportee) ?? [])
      .filter((r) => r.business_unit === undefined || r.business_unit === businessUnit)
      .map((r) => r.reporting_manager);
  }

  role(name: string | undefined, organizationId = DEFAULT_ORGANIZATION_ID): RoleBoundary | undefined {
    return name ? this.roles.get(organizationId)?.get(name) : undefined;
  }

  /**
   * Explicit grants add to the actor's role boundary: every live grant on the
   * resource is unioned, and what they do not allow falls through to the role
   * scopes. A narrow share never takes away what the role already gave.
   * Object grants (platform shares) never imply `act`: acting on a step stays
   * with its holders. Deny by default.
   */
  can(
    actor: DirectoryUser,
    action: RbacAction,
    resource: RbacResource,
    options: { ignoreGrants?: boolean } = {},
  ): boolean {
    const organizationId = resource.organization_id ?? DEFAULT_ORGANIZATION_ID;
    const actorOrganizationId = actor.organization_id ?? DEFAULT_ORGANIZATION_ID;
    if (actorOrganizationId !== organizationId) return false;

    // ignoreGrants: ask only whether the actor's role carries a standing scope
    // (the supervising-role bypass must not be bought with a share).
    const now = Date.now();
    // An unreadable expiry counts as expired, never as "forever".
    const live = (g: ExplicitGrant) =>
      g.expires_at === undefined || !(Number.isNaN(Date.parse(g.expires_at)) || Date.parse(g.expires_at) <= now);
    const grants = options.ignoreGrants ? [] : (this.grants.get(organizationId) ?? []).filter(
      (g) =>
        g.is_active !== false &&
        g.user_id === actor.id &&
        live(g) &&
        ((g.resource_type === resource.type && g.resource_id === resource.id) ||
          (g.resource_type === 'object' && resource.object_key !== undefined && g.resource_id === resource.object_key)),
    );
    const granted = grants.some(
      (g) =>
        (action !== 'act' || g.resource_type !== 'object') &&
        (g.actions.includes(action) ||
          g.actions.includes('admin') ||
          (action === 'act' && g.actions.includes('write'))),
    );
    if (granted) return true;

    const boundary = this.role(actor.role as string | undefined, organizationId);
    if (!boundary) return false;

    const object = resource.object_name ?? 'Actionable';
    return boundary.permissions
      .filter((p) => p.object_name === object || (!resource.require_object_permission && !p.object_name))
      .some((p) => this.scopeAllows(p.permission, actor, action, resource, organizationId));
  }

  /**
   * Whether the actor may choose who holds a step: an instance admin, or a
   * role that edits the record across its org, unit or department. Holding a
   * step, having created the item, managing a holder and shares do not count.
   */
  canReassign(actor: DirectoryUser, resource: RbacResource): boolean {
    if (this.can(actor, 'admin', resource)) return true;
    const organizationId = resource.organization_id ?? DEFAULT_ORGANIZATION_ID;
    if ((actor.organization_id ?? DEFAULT_ORGANIZATION_ID) !== organizationId) return false;
    const boundary = this.role(actor.role as string | undefined, organizationId);
    if (!boundary) return false;
    const object = resource.object_name ?? 'Actionable';
    return boundary.permissions
      .filter((p) => SUPERVISING_SCOPES.has(p.permission))
      .filter((p) => p.object_name === object || (!resource.require_object_permission && !p.object_name))
      .some((p) => this.scopeAllows(p.permission, actor, 'write', resource, organizationId));
  }

  private scopeAllows(
    scope: PermissionScope,
    actor: DirectoryUser,
    action: RbacAction,
    resource: RbacResource,
    organizationId: string,
  ): boolean {
    const assigned = resource.assignees?.includes(actor.id) ?? false;
    const resourceDepts = [resource.department, ...(resource.departments ?? [])].filter(Boolean);
    // POST /directory does not validate the list: a non-array must not throw here
    const actorList = Array.isArray(actor.departments) ? actor.departments : [];
    const actorDepts = new Set([actor.department, ...actorList].filter(Boolean));
    const sameDept = resourceDepts.some((d) => actorDepts.has(d));
    const sameBusinessUnit =
      resource.business_unit !== undefined &&
      resource.business_unit === actor.business_unit;
    const hasReportee =
      resource.assignees?.some((a) =>
        this.managers(a, resource.business_unit, organizationId).includes(actor.id),
      ) ?? false;

    switch (scope) {
      case 'OrganizationRead':
        return action === 'read';
      case 'OrganizationReadUpdate':
        return action === 'read' || action === 'write' || action === 'act';
      case 'All':
        return true;
      case 'AssignedReadAll':
        // Read-only on the item, but the holder still acts on their own step.
        return (action === 'read' || action === 'act') && assigned;
      case 'AssignedReadUpdateAll':
        return (action === 'read' || action === 'write' || action === 'act') && assigned;
      case 'SelfCreatedAll':
        // Creating a thing does not make you its administrator. `admin` gates
        // the controls that exist to constrain participants — lifting a
        // comment/evidence demand, activating a dormant step — and whoever
        // attached an instance is a participant like any other.
        return action !== 'admin' && resource.created_by === actor.id;
      case 'DepartmentAssignedReadAll':
        return action === 'read' && sameDept;
      case 'DepartmentAssignedReadUpdateAll':
        return (action === 'read' || action === 'write' || action === 'act') && sameDept;
      case 'BusinessUnitAssignedReadAll':
        return action === 'read' && sameBusinessUnit;
      case 'BusinessUnitAssignedReadUpdateAll':
        return (action === 'read' || action === 'write' || action === 'act') && sameBusinessUnit;
      case 'ReporteeAssignedReadUpdateAll':
        return (action === 'read' || action === 'write' || action === 'act') && hasReportee;
      default:
        return false;
    }
  }
}
